struct Params { time: f32 }
@group(0) @binding(0) var<uniform> params: Params;

fn hash(p: vec2f) -> f32 {
  return fract(sin(dot(p, vec2f(127.1, 311.7))) * 43758.5453123);
}

fn noise(p: vec2f) -> f32 {
  let i = floor(p);
  let f = fract(p);
  let u = f * f * (3.0 - 2.0 * f);
  return mix(
    mix(hash(i), hash(i + vec2f(1.0, 0.0)), u.x),
    mix(hash(i + vec2f(0.0, 1.0)), hash(i + vec2f(1.0, 1.0)), u.x),
    u.y
  );
}

fn fbm(p: vec2f) -> f32 {
  var v = 0.0;
  var a = 0.5;
  var x = p;
  for (var i = 0; i < 3; i++) {
    v += a * noise(x);
    x = x * 2.07 + vec2f(11.3, 5.7);
    a *= 0.5;
  }
  return v;
}

@fragment fn fs_main(@location(0) uv: vec2f) -> @location(0) vec4f {
  let t = params.time;
  let x = uv.x;
  let y = 1.0 - uv.y;

  var col = mix(vec3f(0.006, 0.008, 0.022), vec3f(0.016, 0.020, 0.052), y);
  col = mix(col, vec3f(0.045, 0.028, 0.075), smoothstep(0.58, 1.0, y) * 0.40);

  let g = uv * vec2f(64.0, 114.0);
  let id = floor(g);
  let fc = fract(g) - 0.5;
  let h = hash(id);
  let tw = 0.55 + 0.45 * sin(t * 1.6 + h * 38.0);
  let star = smoothstep(0.030, 0.0, length(fc)) * step(0.875, h) * tw * (0.30 + 0.70 * hash(id + 4.2));
  col += vec3f(0.80, 0.86, 1.0) * star * smoothstep(0.12, 0.30, y);

  var aur = vec3f(0.0);
  for (var i = 0; i < 4; i++) {
    let fi = f32(i);
    let n = fbm(vec2f(x * (1.7 + fi * 0.38) + t * (0.11 + fi * 0.035), y * 0.52 + fi * 1.65 + t * 0.045));
    let nx = x + (n - 0.5) * (0.24 + fi * 0.07);
    let ridge = 0.5 + 0.5 * sin(nx * (7.4 + fi * 2.2) + t * (0.17 + fi * 0.06) + fi * 1.25);
    let sheet = pow(ridge, 9.0 + fi * 1.8);
    let height = smoothstep(0.10, 0.24, y) * smoothstep(0.96, 0.40, y);
    let glow = sheet * height * pow(max(n * 0.5 + ridge * 0.5, 0.0), 1.25);
    let veil = pow(n, 1.55) * height * 0.52;
    let fringe = pow(ridge, 4.0) * (1.0 - pow(ridge, 7.0)) * height;
    let k = clamp(y * 1.12 - 0.12 + fi * 0.04, 0.0, 1.0);
    let tone = mix(vec3f(0.16, 0.95, 0.38), mix(vec3f(0.22, 0.82, 0.78), vec3f(0.68, 0.22, 1.0), k), k);
    aur += tone * (glow * (0.88 - fi * 0.12) + veil * 0.26);
    aur += vec3f(0.72, 0.24, 0.95) * fringe * (0.28 - fi * 0.04);
  }

  col += aur;
  col += vec3f(0.10, 0.48, 0.24) * pow(clamp(aur.g, 0.0, 1.0), 1.7) * 0.22;

  let hill = 0.075 + 0.028 * sin(x * 6.4 + 0.4) + 0.016 * sin(x * 13.5 + 1.7);
  let ground = smoothstep(hill + 0.018, hill - 0.006, y);
  col = mix(col, vec3f(0.004, 0.006, 0.012), ground);
  let hz = exp(-abs(y - hill - 0.02) * 22.0) * clamp(aur.g + aur.b, 0.0, 1.0);
  col += vec3f(0.07, 0.20, 0.12) * hz * 0.32 * (1.0 - ground);

  let vig = smoothstep(1.18, 0.32, length((uv - vec2f(0.5, 0.52)) * vec2f(1.12, 0.92)));
  col *= 0.58 + 0.42 * vig;

  return vec4f(col, 1.0);
}
